 density=[
 {'Manuscript':'International','Core_Claims':1,'Supporting_Claims':3,'Contextual_Claims':0,'Independent_Cohorts_or_Source_Families':3,'Result_IDs':4,'Unique_Evidence_IDs':4,'Direct_Evidence':'1 sleep/caffeine review; task-boundary examples are indirect to broad readiness','Indirect_Evidence':'Cardiometabolic and Brazilian shooting transferability examples','Narrative_Density':'Sufficient for a short evidence-informed integrative synthesis focused on evidence boundaries and transferability.','Status':'B2_VIABLE_SHORT_FORM'},
 {'Manuscript':'Brazil','Core_Claims':2,'Supporting_Claims':4,'Contextual_Claims':3,'Independent_Cohorts_or_Source_Families':7,'Result_IDs':9,'Unique_Evidence_IDs':9,'Direct_Evidence':'Brazilian PMDF, Paraná, shooting, APH, organizational and musculoskeletal sources','Indirect_Evidence':'International sleep/caffeine is excluded from Brazil working set','Narrative_Density':'Sufficient for a bounded full integrative manuscript with three substantive sections.','Status':'B2_VIABLE_FULL_MANUSCRIPT'}]
 write('FINAL_B2_EVIDENCE_DENSITY.csv',list(density[0]),density)
 cohorts=[
 {'Cohort_Family':'CF-BR-PMES-CFO-2023-01','Evidence_IDs':'EV-1473; EV-1474','Claims':'RC-BRA-SHOOT-01; RC-BRA-SHOOT-02','Independent_Cohort_Count':1,'Control':'Do not represent as independent replications.'},
 {'Cohort_Family':'PMDF_OLDER_MALE_OFFICERS','Evidence_IDs':'EV-1463','Claims':'RC-BRA-CVD-01','Independent_Cohort_Count':1,'Control':'Cross-sectional, sampled-setting only.'},
 {'Cohort_Family':'PARANA_OCCUPATIONAL_COHORT','Evidence_IDs':'EV-1484','Claims':'RC-BRA-MED-01','Independent_Cohort_Count':1,'Control':'No national-prevalence inference.'},
 {'Cohort_Family':'PMES_VILA_VELHA_17TH_COMPANY','Evidence_IDs':'EV-1467','Claims':'RC-GAP2-BRA-MSK-01','Independent_Cohort_Count':1,'Control':'Cross-sectional context only.'}]
 write('FINAL_B2_INDEPENDENT_COHORT_COUNT.csv',list(cohorts[0]),cohorts)
 evrow={'Evidence_ID':'EV-1467','Result_ID':'EV-1467-GAP2-R01','Locator':'Results; Table 1; Tables 2–5','Population':'31 Brazilian military police officers: administrative n=15; tactical n=16','Design':'Cross-sectional comparative study','Permitted_Claim':'In this sample, weekly physical-activity time and reported musculoskeletal discomfort did not differ significantly between sectors.','Classification':'CONTEXTUAL_CLAIM','Prohibited_Inference':'Causal sector effect; prospective readiness prediction; Brazil prevalence; occupational-performance benefit; academy-readiness claim; equivalent health impact.','Core_Claim':'NO','Claim_Ready':'NO','Human_Review':'PENDING'}
