 hq += [{'Review_Item':'International objective and short-form status','Type':'OBJECTIVE_CHANGE','Requested_Human_Decision':'Confirm narrowed International objective','Status':'PENDING','No_Human_Decision_Recorded':'YES'}, {'Review_Item':'Brazil objective and full-manuscript status','Type':'OBJECTIVE_CHANGE','Requested_Human_Decision':'Confirm narrowed Brazil objective','Status':'PENDING','No_Human_Decision_Recorded':'YES'}]
 write('B2_HUMAN_REVIEW_QUEUE.csv',list(hq[0]),hq)
 write('B2_FCR_CANDIDATES.csv',['FCR_Candidate','Status','Reason','Action'],[{'FCR_Candidate':'NONE','Status':'NO','Reason':'Scope pruning and working blueprint do not alter CEF-v1 or frozen wording.','Action':'CEF-v1 unchanged.'}])
 intl='''# INTERNATIONAL B2 — FINAL NARROWED BLUEPRINT\n\n## Title\n\n**Evidence boundaries and transferability in selected operational-readiness domains: an evidence-informed integrative synthesis**\n\n## Central question and objective\n\nWhat can result-located evidence in selected operational-readiness domains support, and where must claims stop because of transferability and evidence-density limits? The objective is to synthesize bounded sleep/caffeine, cardiometabolic-transferability and task-specific performance evidence without presenting a global readiness model.\n\n## Article type\n\nEvidence-informed integrative synthesis; not a systematic review. The `PROPOSED SYNTHESIS FRAMEWORK — NOT YET VALIDATED` remains a conceptual organizer only.\n\n## Claims and structure\n\n- Supporting: task-dependent sleep/caffeine evidence; cardiometabolic transferability context; shooting null-result boundaries.\n- Sections: evidence-boundary framing; selected domain evidence and transferability; limitations and future validation.\n- Removed from core: nutrition/supplementation, physical fitness/academy readiness, hydration/heat.\n\n## Density and viability\n\nFour result IDs across three independent source families support a **short form** (estimated 2,500–3,500 words), not a broad full manuscript. All citations remain working-only and human review is pending.\n\n## Limitations\n\nUnadjudicated contradictory evidence (EV-0052, EV-0140, EV-1066) is not support. No global readiness score, framework validation, causal inference or Brazil-generalization is permitted.\n'''
 brazilmd='''# BRAZIL B2 — FINAL NARROWED BLUEPRINT\n\n## Title\n\n**Evidence boundaries in Brazilian public-safety readiness: a bounded evidence-informed integrative synthesis**\n\n## Central question and objective\n\nWhat do result-located Brazilian public-safety sources support about medical readiness, task-specific performance, tactical medicine and organizational context? The objective is to synthesize the available evidence while retaining null findings, cohort limits and institutional transferability constraints.\n\n## Article type\n\nEvidence-informed integrative synthesis; not a systematic review. The `PROPOSED SYNTHESIS FRAMEWORK — NOT YET VALIDATED` is conceptual only.\n\n## Claims and structure\n\n- Core: bounded cardiometabolic surveillance context; medical non-readiness associations.\n- Supporting: shooting null findings, tourniquet-use record review, Escola Segura null evaluation.\n- Contextual: institutional implementation case and two cross-sectional musculoskeletal observations, including EV-1467.\n- Sections: medical readiness; task-specific and tactical-medicine evidence; organizational/implementation context; limitations and future validation.\n- Removed from core: nutrition/supplementation, physical fitness/academy readiness, hydration/heat.\n\n## Density and viability\n\nNine result IDs across seven independent source families support a **bounded full manuscript** (estimated 3,000–4,000 words). Citations are working-only and human review remains pending.\n\n## Limitations\n\nEvidence is heterogeneous and mostly observational or descriptive; the shooting publications overlap in one cohort; no national prevalence, causal, intervention-effect, framework-validation or global-readiness inference is permitted.\n'''
 (OUT/'INTERNATIONAL_B2_BLUEPRINT.md').write_text(intl,encoding='utf-8'); (OUT/'BRAZIL_B2_BLUEPRINT.md').write_text(brazilmd,encoding='utf-8')
 report='''# BATCH 10.4H-B2 — Architecture B scope pruning\n\n## Gate\n\n`ARCHITECTURE_B2_SCOPE_PRUNING_PASS`\n\n## Decision\n\nThe three unresolved domains are removed from core scope: nutrition/supplementation, physical fitness/academy readiness and hydration/heat. They may appear only as limitations, structural gaps or future-research needs. EV-0052, EV-0140 and EV-1066 remain unadjudicated contradictory evidence and have zero support use.\n\n## Viability\n\n- **International:** `B2_VIABLE_SHORT_FORM` — four retained result IDs across three independent source families, suitable for an evidence-boundary and transferability synthesis.\n- **Brazil:** `B2_VIABLE_FULL_MANUSCRIPT` — nine retained result IDs across seven independent source families, suitable for a bounded evidence-informed integrative synthesis.\n\nEV-1467 is incorporated only as a contextual, small, cross-sectional Brazilian null-result packet. No manuscript, Zotero, CEF-v1 or frozen reference set was changed. Human review remains pending.\n\n## Next gate\n\n`BATCH 10.4H-R — EVIDENCE-FIRST v0.15 RECONSTRUCTION RETRY` may proceed only with these blueprints and their stated limits.\n'''
 (OUT/'BATCH10_4H_B2_REPORT.md').write_text(report,encoding='utf-8')
 fs=[p for p in OUT.iterdir() if p.is_file() and p.name!='BATCH10_4H_B2_MANIFEST.json']
 m={'batch':'BATCH 10.4H-B2','base_commit':'c6a42b65d145ab5d7205bdee4a81c08eeeb2210a','gate':'ARCHITECTURE_B2_SCOPE_PRUNING_PASS','international_status':'B2_VIABLE_SHORT_FORM','brazil_status':'B2_VIABLE_FULL_MANUSCRIPT','claims_total':len(claims),'claims_retained':sum(r['B2_Disposition']!='REMOVE_FROM_MANUSCRIPT' for r in claims),'claims_removed':sum(r['B2_Disposition']=='REMOVE_FROM_MANUSCRIPT' for r in claims),'unresolved_domains_promoted_to_core':0,'hydration_claims_without_result_id':0,'nutrition_claims_relying_on_EV0140':0,'fitness_core_claims_relying_on_EV0052_or_EV1066':0,'source_insufficient_evidence_promoted':0,'blocked_evidence_support':0,'cohort_double_counting':0,'null_suppression':0,'framework_validation_inflation':0,'CEF_v1_unauthorized_change':0,'Zotero_changed':0,'v015_changed':0,'human_review':'PENDING','deterministic_regeneration':'python analysis/build_batch10_4h_b2.py','artifact_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in fs}}
